import test from "node:test";
import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {publicReadiness} from "./kilowallet-public-readiness.mjs";
const now=Date.parse("2026-11-06T05:40:00Z");
function fixture(){
 const metadata=JSON.parse(readFileSync(new URL("../release/KILOWALLET-100-BUILD8-REVIEW-METADATA-PREPARED.json",import.meta.url)));
 metadata.additionalNativeVerification.visualApproved=true; metadata.additionalNativeVerification.publicAdvanceApproved=true;
 const {app,appleBuildId:buildId,sourceCommit,ipaSha256,build,marketingVersion}=metadata;
 return {metadata,beta:{app,buildId,sourceCommit,ipaSha256,build,marketingVersion,complete:true,readOnly:true,writes:[],observedAt:new Date(now).toISOString(),uploadRunId:42137139153,uploadRunAttempt:1,memberships:["8f0948f4-86ef-4f7a-aa47-830a6e8f4eae","f4f2520c-3eaf-46f9-a31a-a36d38b74c53"].map(id=>({id,buildSide:true,groupSide:true})),internalState:"IN_BETA_TESTING",externalState:"IN_BETA_TESTING",review:{buildId,state:"APPROVED"},available:true},listing:{appId:app,app:{id:app,bundleId:metadata.bundleId},mode:"read-only",inspectionComplete:true,errors:[],observedAt:new Date(now).toISOString(),availability:{territories:["USA"],availableInNewTerritories:false},uploadedBuild:{build:"3"},appStoreVersions:[{id:"1ca23695-4563-4a0e-b20e-d1a6457f4f8b",version:"0.4.0",platform:"IOS",state:"WAITING_FOR_REVIEW"}]},visual:{run:42163150260,attempt:1,job:127713335608,capturePassed:true,framesReviewed:4,allTextRendered:true,artifactSha256:"a".repeat(64)},privacy:{app,sourceCommit,buildId,labelsReconciled:true,actualHttpsBridgeDisclosed:true,arkRetentionDisclosed:true,legalAttestations:null}};
}
test("fully qualified synthetic facts permit preparation only, never Apple writes or withdrawal",()=>{const r=publicReadiness(fixture(),now);assert.equal(r.readyForPublicPreparation,true);assert.deepEqual(r.appleWrites,[]);assert.equal(r.preserveExistingReview,true);assert.equal(r.submissionAuthorizedByThisReport,false)});
const rejectionCases={wrongApp:f=>f.beta.app="6817118871",wrongSource:f=>f.beta.sourceCommit="0".repeat(40),wrongPackage:f=>f.beta.ipaSha256="0".repeat(64),wrongBuild:f=>f.beta.build="3",staleBeta:f=>f.beta.observedAt="2026-11-06T05:00:00Z",futureListing:f=>f.listing.observedAt="2026-11-06T05:41:00Z",duplicateGroups:f=>f.beta.memberships[1]=f.beta.memberships[0],foreignGroups:f=>f.beta.memberships[1].id="foreign",wrongScope:f=>f.listing.availability.territories.push("FRA"),automaticExpansion:f=>f.listing.availability.availableInNewTerritories=true,failedListing:f=>f.listing.errors.push("failed read"),wrongNativeAttempt:f=>f.metadata.additionalNativeVerification.attempt=1,implicitAttestation:f=>f.metadata.legalAttestations={},agreementAcceptance:f=>f.metadata.agreementAcceptance=true};
for(const [name,mutate] of Object.entries(rejectionCases))test(name+" rejects",()=>{const f=fixture();mutate(f);assert.throws(()=>publicReadiness(f,now))});
const holdCases={pendingApple:f=>{f.beta.externalState="WAITING_FOR_BETA_REVIEW";f.beta.review.state="WAITING_FOR_REVIEW"},missingIndependentMembership:f=>f.beta.memberships[0].groupSide=false,missingGlyphs:f=>f.visual.allTextRendered=false,unreviewedFourthFrame:f=>f.visual.framesReviewed=3,failedCapture:f=>f.visual.capturePassed=false,originalVisualHold:f=>f.metadata.additionalNativeVerification.visualApproved=false,privacyNotReconciled:f=>f.privacy.labelsReconciled=false,missingPrivacy:f=>delete f.privacy,oldReviewChanged:f=>f.listing.appStoreVersions[0].state="READY_FOR_DISTRIBUTION",additionalVersion:f=>f.listing.appStoreVersions.push({id:"other",version:"1.0.0",platform:"IOS",state:"PREPARE_FOR_SUBMISSION"})};
for(const [name,mutate] of Object.entries(holdCases))test(name+" keeps old review",()=>{const f=fixture();mutate(f);const r=publicReadiness(f,now);assert.equal(r.readyForPublicPreparation,false);assert.ok(r.blockers.length);assert.deepEqual(r.appleWrites,[]);assert.equal(r.preserveExistingReview,true)});
